from selected_light84 import known
from review_motion64 import srgb
H=Path(__file__).resolve().parent;G=H/'face89/fix2';C=G/'capture'

def linear(p):
 v=p.astype(float)/255;return np.where(v<=.04045,v/12.92,((v+.055)/1.055)**2.4).astype(np.float32)
def main():
 r=json.loads((C/'COMPLETE.json').read_text());assert r['packetComplete']and r['restorationChecksPass']and r['ownedResourcesReleased']and not r['errors'];spec=json.loads((C/'RUNTIME_PALETTE89.json').read_text());rawpalette=(C/'RUNTIME_PALETTE89.rgb').read_bytes();assert hashlib.sha256(rawpalette).hexdigest()==spec['paletteSHA'];levels=spec['levels'];palette=np.frombuffer(rawpalette,np.uint8).reshape(-1,levels,3);p=linear(palette);old=linear(np.fromfile(H/'face88/PALETTE88.rgb',np.uint8).reshape(-1,levels,3));source=np.load(H/'face88/SOURCE_VALUE88.npz');labels=source['labels'];native=np.load(H/'face28/SOURCE_NATIVE28.npz');native_rgba=native['rgba'];info=json.loads((H/'face28/SOURCE_INPUT28.json').read_text());ox,oy=info['cropOffset'];tw,th=info['textureSize'];rows=[];panels=[];film=[];count=0;source_error=[];source_code_error=[];bad_roundtrip=0;without_history=0
 for f in r['stream77']['frames']:
  w,h=f['QROI'][2:];b=decode((C/f['compressedFile']).read_bytes(),f['bytes']);assert hashlib.sha256(b).hexdigest()==f['rawSHA256'];a=np.frombuffer(b,'<f4').reshape(h,22,w,4).transpose(1,0,2,3);visible=a[12,:,:,3]==1;assert np.array_equal(a[20,:,:,3]==1,visible);assert not(a[20,:,:,0]<0).any();expected_known=known(a[3],a[4],a[6],a[7],a[9],a[11],a[13],a[5],a[8]);assert np.array_equal(expected_known,visible)
  ids=a[20,:,:,0].astype(int)-1;k=a[20,:,:,1].astype(int);kh=a[20,:,:,2].astype(int);assert np.array_equal(k[visible],np.rint(a[8,:,:,0][visible]*(levels-1)).astype(int));assert np.array_equal(kh[visible],np.rint(a[16,:,:,0][visible]*(levels-1)).astype(int));uv=a[11,:,:,:2].astype(float);x=np.floor(uv[:,:,0]*tw).astype(int)-ox;y=np.floor((1-uv[:,:,1])*th).astype(int)-oy;assert np.array_equal(ids[visible],labels[y[visible],x[visible]])
  for plane,table,kk in [(17,old,kh),(18,p,k),(19,p,kh)]:
   assert np.array_equal(a[plane][visible,:3],table[ids[visible],kk[visible]]),(f['frame'],plane,'finite RGB lookup mismatch');assert np.array_equal(a[plane,:,:,3],a[0,:,:,3]);assert np.array_equal(a[plane][~visible],a[0][~visible]),(f['frame'],plane,'nonface/occlusion overwrite')
  observed=a[21][visible,:3];rgb8=native_rgba[y[visible],x[visible],:3];expected=linear(rgb8);error=float(np.max(abs(observed-expected),initial=0));source_error.append(error);encoded=np.where(observed<=.0031308,observed*12.92,1.055*np.power(np.maximum(observed,0),1/2.4)-.055)*255;source_code_error.append(float(np.max(abs(encoded-rgb8),initial=0)));bad_roundtrip+=int(np.count_nonzero(np.rint(encoded)!=rgb8));missing_history=visible&(a[16,:,:,3]!=1);without_history+=int(missing_history.sum());count+=int(visible.sum());ims=[srgb(a[z])for z in [0,17,18,19]];panels.append((f,ims));draw_frame=Image.new('RGB',(w*8*3,h*8+24),(27,29,35));ImageDraw.Draw(draw_frame).text((4,4),f"Actual GPU F{f['frame']}: native / source current / source history",fill='white')
  for j,im in enumerate([ims[0],ims[2],ims[3]]):draw_frame.paste(im.resize((w*8,h*8),Image.Resampling.NEAREST),(j*w*8,24))
  film.append(draw_frame);rows.append({'frame':f['frame'],'sourceId':f['sourceId'],'eligibleFaceCells':int(visible.sum()),'currentColourValidWithoutHistory':int(missing_history.sum()),'finiteLUTOutsideColours':0,'unknownSourceAddresses':0,'nonfaceHairEyeOrAlphaChanges':0,'originalTexturePointVersusOriginalPNGLinearMaxError':error,'historyRGBChangesFromSameFrameCurrentQ':int(np.count_nonzero((a[18]!=a[19]).any(2))),'nativeFaceUniqueRGB8':len(np.unique(np.array(ims[0])[np.flipud(visible)],axis=0))if visible.any()else 0,'candidateFaceUniqueRGB8':len(np.unique(np.array(ims[3])[np.flipud(visible)],axis=0))if visible.any()else 0})
 selected=[panels[i]for i in np.unique(np.linspace(0,len(panels)-1,min(8,len(panels))).astype(int))];board=Image.new('RGB',(1200,len(selected)*185+45),(27,29,35));draw=ImageDraw.Draw(board)
 for i,(f,ims)in enumerate(selected):
  for j,(im,title)in enumerate(zip(ims,['Actual native RGB','Actual old-unit LUT control','Actual source89/current Q','Actual source89/GPU Q history'])):
   draw.text((j*300+3,i*185+4),f"F{f['frame']} {title}",fill='white');board.paste(im,(j*300+3,i*185+25));board.paste(im.resize((w*5,h*5),Image.Resampling.NEAREST),(j*300+45,i*185+25))
 name='91'if G.name=='face91'or G.parent.name=='face91'else'89';draw.text((4,len(selected)*185+8),'Actual private raster RGB, no CPU RGB replay. Native alpha/other parts/current visibility retained. Product77 unchanged.',fill='white');draw.text((4,len(selected)*185+26),'Source-hue policy omits legacy face tint; artistic choice and general line width/long gameplay stability remain separate.',fill='white');board.save(G/f'ACTUAL_COLOUR{name}.png');film[0].save(G/f'ACTUAL_COLOUR{name}.webp',save_all=True,append_images=film[1:],duration=150,loop=0,lossless=True)
 out={'actualGPUFrames':len(rows),'eligibleFaceSamples':count,'currentColourValidWithoutHistory':without_history,'finiteRGBLookupExact':True,'nonfaceHairEyeAndAlphaChanges':0,'sourceValueAddresses':len(palette),'liveLinearFloor':spec['liveLinearFloor'],'adaptedLabRatio':spec['adaptedLabRatio'],'legacyFaceTintReapplied':spec['legacyFaceTintReapplied'],'originalSourceTexturePointMaxLinearError':max(source_error,default=0),'originalSourceTexturePointMaxCodeError':max(source_code_error,default=0),'originalRGB8RoundtripDifferentChannels':bad_roundtrip,'actualSourceTextureFormatReported':spec['originalFormat'],'newColourIsActualGPU':True,'CPUSelectionOrRGBUploaded':False,'simulationSeconds':len(rows)/60,'longGameplayStabilityProven':False,'generalLineWidthOrFullArtAdopted':False,'restorationChecksPass':True,'ownedResourcesReleased':True,'rows':rows};(G/f'ACTUAL_COLOUR{name}.json').write_text(json.dumps(out,indent=2));print(json.dumps({k:v for k,v in out.items()if k!='rows'}))
